let currentCategory = null;
let currentIndex = 0;
function displayCategoryProducts(category) {
  currentCategory = category;
  currentIndex = 0;
  updateProductList();
}
function updateProductList() {
  const productList = document.getElementById('product-list');
  const categoryTitle = document.getElementById('category-title');
  const products = productsData[currentCategory];
  productList.innerHTML = '';

  
  categoryTitle.textContent = currentCategory.charAt(0).toUpperCase() + currentCategory.slice(1);

  for (let i = currentIndex; i < currentIndex + 3 && i < products.length; i++) {
    const product = products[i];
    const productDiv = document.createElement('div');
    productDiv.classList.add('product');
    productDiv.innerHTML = `
      
	  <h3>${product.name}</h3>
      <p>Brand: ${product.brand}</p>
      <p>Price: ${product.price}</p>
      <img src="${product.image}" alt="${product.name}">
      <button class="buy-button">Buy</button>
      <button class="add-to-cart-button">Add to Cart</button>
	 
    `;
    productList.appendChild(productDiv);
  }

  document.getElementById('prev-button').style.display = currentIndex > 0 ? 'block' : 'none';
  document.getElementById('next-button').style.display = currentIndex + 3 < products.length ? 'block' : 'none';

  document.getElementById('home').style.display = 'none';
  document.getElementById('category-details').style.display = 'block';
}
document.querySelectorAll('.category').forEach(button => {
  button.addEventListener('click', () => {
    const category = button.getAttribute('data-category');
    displayCategoryProducts(category);
  });
});
document.getElementById('prev-button').addEventListener('click', () => {
  if (currentIndex > 0) {
    currentIndex -= 3;
    updateProductList();
  }
});

document.getElementById('next-button').addEventListener('click', () => {
  const products = productsData[currentCategory];
  if (currentIndex + 3 < products.length) {
    currentIndex += 3;
    updateProductList();
  }
});

document.getElementById('back-button').addEventListener('click', () => {
  document.getElementById('home').style.display = 'block';
  document.getElementById('category-details').style.display = 'none';
});


